{% layout 'layouts/base' %}
{% comment %} home: the sections named in home.yml, top to bottom. {% endcomment %}
{% block content %}
{%- for name in home.sections %}
{% assign tpl = 'sections/' | append: name %}
{% render tpl, site: site, t: t, page: page, home: home, photos: photos, moments: moments, hours_rows: hours_rows, events_next: events_next, events_url: events_url, gallery_url: gallery_url, menu: menu %}
{%- endfor %}
{% endblock %}

files.templates/layouts/page.liquid:
{% layout 'layouts/base' %}
{% comment %} page: a plain text page from a Markdown file: title and prose. {% endcomment %}
{% block content %}
<section class="section">
  <div class="wrap prose">
    <h1 class="h-xl">{{ page.title }}</h1>
    {{ page.content | raw }}
  </div>
</section>
{% endblock %}

